import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class KeyedObjects2D_removeObject_TriageGen2Test {

    private KeyedObjects2D dataset;

    @Before
    public void setUp() {
        dataset = new KeyedObjects2D();
    }

    @Test
    public void testRemoveObject_DoesNotRemoveRowOrColumn() {
        // Setup: 2x2 grid
        dataset.addObject("Value1", "R1", "C1");
        dataset.addObject("Value2", "R1", "C2");
        dataset.addObject("Value3", "R2", "C1");

        // Action: Remove one element
        dataset.removeObject("R1", "C1");

        // Assert: Row R1 still exists because of C2, Column C1 still exists because of R2
        assertEquals(2, dataset.getRowCount());
        assertEquals(2, dataset.getColumnCount());
        assertNull(dataset.getObject("R1", "C1"));
        assertEquals("Value2", dataset.getObject("R1", "C2"));
        assertEquals("Value3", dataset.getObject("R2", "C1"));
    }










}

