    @Test
    public void testRemoveObject_RemovesRowWhenEmpty() {
        // Setup: 1x1 grid
        dataset.addObject("Value1", "R1", "C1");

        // Action: Remove the only element
        dataset.removeObject("R1", "C1");

        // Assert: Row R1 is removed, but Column C1 remains (logic: column check happens after row removal)
