import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class KeyedObjects2D_removeObject_TriageGen2Test {

    private KeyedObjects2D dataset;

    @Before
    public void setUp() {
        dataset = new KeyedObjects2D();
    }





    @Test
    public void testRemoveObject_RemovesColumnWhenEmpty() {
        // Setup: 2x1 grid
        dataset.addObject("V1", "R1", "C1");
        dataset.addObject("V2", "R2", "C1");

        // Action: Remove elements such that column becomes empty
        // Since we can't remove one by one to trigger the column logic without clearing the row,
        // we simulate the state where row removal logic is bypassed or handled.
        // In the provided code, if we remove "R1, C1", R1 is not empty (has C2 if we added it).
        // To test column removal: we need all rows to have null at that column index.

        dataset.addObject("V3", "R1", "C2");
        dataset.addObject("V4", "R2", "C2");

        // Current state:
        // R1: C1=V1, C2=V3
        // R2: C1=V2, C2=V4

        dataset.removeObject("R1", "C1");
        dataset.removeObject("R2", "C1");

        // Now Column C1 should be gone
        assertEquals(2, dataset.getRowCount());
        assertEquals(1, dataset.getColumnCount());
        assertEquals("C2", dataset.getColumnKeys().get(0));
    }






}

