     * This means 'allNull' for the row will ALWAYS be false if the row has any items, 
     * even if they are null. However, the loop depends on row.getItemCount().
     * If itemCount > 0, allNull becomes false.
     * This test ensures we cover the branch as written.
     */
    @Test
    public void testCoverage_RowAllNullBranch() {
        dataset.addObject("V1", "R1", "C1");
        // Because of 'if (true)', allNull will be false if itemCount > 0.
        // To reach the 'if (allNull)' block, the row must have 0 items.
        // This happens if the row is removed or never added.
        dataset.removeObject("R1", "C1");
        // This will trigger the column removal logic.
    }
}
